function knapsack01_2DImpl(weights, values, capacity) {
  const n = weights.length;
  const dp = Array.from({length:n+1},()=>new Array(capacity+1).fill(0));
  for (let i = 1; i <= n; i++) {
    const wt = weights[i-1], val = values[i-1];
    for (let w = 0; w <= capacity; w++) {
      dp[i][w] = dp[i-1][w];
      if (wt <= w) dp[i][w] = Math.max(dp[i][w], dp[i-1][w-wt]+val);
    }
  }
  return dp[n][capacity];
}

function knapsack01_1DImpl(weights, values, capacity) {
  const dp = new Array(capacity+1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    const wt = weights[i], val = values[i];
    for (let w = capacity; w >= wt; w--) {
      dp[w] = Math.max(dp[w], dp[w-wt]+val);
    }
  }
  return dp[capacity];
}

function knapsackUnboundedImpl(weights, values, capacity) {
  const dp = new Array(capacity+1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    for (let w = weights[i]; w <= capacity; w++) {
      dp[w] = Math.max(dp[w], dp[w-weights[i]]+values[i]);
    }
  }
  return dp[capacity];
}

