function findTargetSumWaysImpl(nums, target) {
  const sum = nums.reduce((a,b) => a+b, 0);
  if ((sum + target) % 2 !== 0) return 0;
  if (Math.abs(target) > sum) return 0;
  const st = (sum + target) / 2;
  const dp = new Array(st + 1).fill(0);
  dp[0] = 1;
  for (const num of nums)
    for (let j = st; j >= num; j--)
      dp[j] += dp[j - num];
  return dp[st];
}

function findTargetSumWaysDFS(nums, target) {
  let count = 0;
  function dfs(i, current) {
    if (i === nums.length) { if (current === target) count++; return; }
    dfs(i+1, current + nums[i]);
    dfs(i+1, current - nums[i]);
  }
  dfs(0, 0);
  return count;
}

