function canPartitionImpl(nums) {
  const total = nums.reduce((a,b)=>a+b, 0);
  if (total % 2 !== 0) return false;
  const target = total / 2;
  const dp = new Array(target + 1).fill(false);
  dp[0] = true;
  for (const num of nums) {
    for (let j = target; j >= num; j--)
      if (dp[j - num]) dp[j] = true;
    if (dp[target]) return true;
  }
  return dp[target];
}

function findPartition(nums) {
  const total = nums.reduce((a,b)=>a+b, 0);
  if (total % 2 !== 0) return null;
  const target = total / 2;
  const n = nums.length;
  const dp = Array.from({length:n+1},()=>new Array(target+1).fill(false));
  for (let i = 0; i <= n; i++) dp[i][0] = true;
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j <= target; j++) {
      dp[i][j] = dp[i-1][j];
      if (nums[i-1] <= j) dp[i][j] = dp[i][j] || dp[i-1][j-nums[i-1]];
    }
  }
  if (!dp[n][target]) return null;
  const result = [];
  let j = target;
  for (let i = n; i > 0; i--) {
    if (!dp[i-1][j]) { result.push(nums[i-1]); j -= nums[i-1]; }
  }
  return result;
}

